class=\\\"fisica-docentes-row\\\" data-search=\\\"sandro fonseca de souza f&iacute;sica experimental de altas energias 3016-a\\\"><td data-label=\\\"Docente\\\">Sandro Fonseca de Souza<\\/td><td data-label=\\\"&Aacute;rea de pesquisa\\\">F&iacute;sica Experimental de Altas Energias<\\/td><td data-label=\\\"Sala\\\">3016-A<\\/td><td data-label=\\\"Lattes\\\"><a href=\\\"http:\\/\\/lattes.cnpq.br\\/4560612419350680\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" aria-label=\\\"Abrir curr&iacute;culo Lattes de Sandro Fonseca de Souza\\\">Acessar<\\/a><\\/td><\\/tr><tr class=\\\"fisica-docentes-row\\\" data-search=\\\"wagner de paula carvalho f&iacute;sica experimental de altas energias 3030-a\\\"><td data-label=\\\"Docente\\\">Wagner de Paula Carvalho<\\/td><td data-label=\\\"&Aacute;rea de pesquisa\\\">F&iacute;sica Experimental de Altas Energias<\\/td><td data-label=\\\"Sala\\\">3030-A<\\/td><td data-label=\\\"Lattes\\\"><a href=\\\"http:\\/\\/lattes.cnpq.br\\/7615867204448572\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" aria-label=\\\"Abrir curr&iacute;culo Lattes de Wagner de Paula Carvalho\\\">Acessar<\\/a><\\/td><\\/tr><tr class=\\\"fisica-docentes-row\\\" data-search=\\\"walter luiz alda junior f&iacute;sica experimental de altas energias 3024-a\\\"><td data-label=\\\"Docente\\\">Walter Luiz Alda Junior<\\/td><td data-label=\\\"&Aacute;rea de pesquisa\\\">F&iacute;sica Experimental de Altas Energias<\\/td><td data-label=\\\"Sala\\\">3024-A<\\/td><td data-label=\\\"Lattes\\\"><a href=\\\"http:\\/\\/lattes.cnpq.br\\/5721137820988643\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" aria-label=\\\"Abrir curr&iacute;culo Lattes de Walter Luiz Alda Junior\\\">Acessar<\\/a><\\/td><\\/tr>\\n          <\\/tbody>\\n        <\\/table>\\n      <\\/div>\\n\\n      <div class=\\\"fisica-docentes-empty\\\" hidden>\\n        Nenhum docente encontrado para a busca nesta &aacute;rea.\\n      <\\/div>\\n    <\\/section>\\n  <\\/div>\\n\\n  \\n    \\n  \\n    \\n  \\n  <script>\\n    (() => {\\n      const app = document.querySelector(\'[data-docentes-app]\');\\n      if (!app || app.dataset.ready === \'true\') {\\n        return;\\n      }\\n      app.dataset.ready = \'true\';\\n\\n      const tabs = Array.from(app.querySelectorAll(\'[data-docentes-tab]\'));\\n      const panels = Array.from(app.querySelectorAll(\'.fisica-docentes-panel\'));\\n      const search = app.querySelector(\'[data-docentes-search]\');\\n      const feedback = app.querySelector(\'[data-docentes-feedback]\');\\n      const total = app.querySelector(\'[data-docentes-total]\');\\n\\n      const updateTotal = () => {\\n        if (!total) {\\n          return;\\n        }\\n\\n        total.textContent = String(app.querySelectorAll(\'.fisica-docentes-row\').length);\\n      };\\n\\n      const activate = (index) => {\\n        tabs.forEach((tab, tabIndex) => {\\n          const active = tabIndex === index;\\n          tab.classList.toggle(\'is-active\', active);\\n          tab.setAttribute(\'aria-selected\', active ? \'true\' : \'false\');\\n        });\\n\\n        panels.forEach((panel, panelIndex) => {\\n          const active = panelIndex === index;\\n          panel.classList.toggle(\'is-active\', active);\\n          panel.hidden = !active;\\n        });\\n\\n        filterRows();\\n      };\\n\\n      const filterRows = () => {\\n        const activePanel = app.querySelector(\'.fisica-docentes-panel.is-active\');\\n        if (!activePanel) {\\n          return;\\n        }\\n\\n        const term = (search?.value || \'\').trim().toLowerCase();\\n        const rows = Array.from(activePanel.querySelectorAll(\'.fisica-docentes-row\'));\\n        let visible = 0;\\n\\n        rows.forEach((row) => {\\n          const haystack = row.dataset.search || \'\';\\n          const match = term === \'\' || haystack.includes(term);\\n          row.hidden = !match;\\n          if (match) {\\n            visible += 1;\\n          }\\n        });\\n\\n        const empty = activePanel.querySelector(\'.fisica-docentes-empty\');\\n        if (empty) {\\n          empty.hidden = visible === 0 ? false : true;\\n        }\\n\\n        if (feedback) {\\n          if (term === \'\') {\\n            feedback.textContent = \'Consulte a rela\\u00e7\\u00e3o completa de docentes por \\u00e1rea.\';\\n          } else {\\n            feedback.textContent = visible + \' docente(s) encontrado(s) na \\u00e1rea selecionada.\';\\n          }\\n        }\\n      };\\n\\n      const activateFromHash = (shouldScroll = false) => {\\n        const hash = decodeURIComponent(window.location.hash || \'\').replace(\\/^#\\/, \'\').trim().toLowerCase();\\n        if (!hash) {\\n          return false;\\n        }\\n\\n        const index = panels.findIndex((panel) => panel.id.toLowerCase() === hash);\\n        if (index === -1) {\\n          return false;\\n        }\\n\\n        activate(index);\\n\\n        if (shouldScroll) {\\n          const targetPanel = panels[index];\\n          window.requestAnimationFrame(() => {\\n            targetPanel.scrollIntoView({ behavior: \'auto\', block: \'start\' });\\n          });\\n        }\\n\\n        return true;\\n      };\\n\\n      tabs.forEach((tab) => {\\n        tab.addEventListener(\'click\', () => {\\n          const index = Number(tab.dataset.docentesTab || 0);\\n          activate(index);\\n\\n          const targetPanel = panels[index];\\n          if (targetPanel?.id) {\\n            history.replaceState(null, \'\', \'#\' + targetPanel.id);\\n            window.requestAnimationFrame(() => {\\n              targetPanel.scrollIntoView({ behavior: \'auto\', block: \'start\' });\\n            });\\n          }\\n        });\\n      });\\n\\n      window.addEventListener(\'hashchange\', () => {\\n        activateFromHash(true);\\n      });\\n\\n      search?.addEventListener(\'input\', filterRows);\\n      updateTotal();\\n      if (!activateFromHash(true)) {\\n        activate(0);\\n      }\\n    })();\\n  \\n  <\\/script>\\n<\\/section>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\",\"scripts\":[],\"styles\":[]}}'),(9132,1433,'_elementor_template_type','wp-page'),(9133,1433,'_elementor_version','3.32.1'),(9134,1433,'_wp_page_template','default'),(9135,1433,'_elementor_data','[{\"id\":\"homehero1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"homehtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<section class=\\\"fisica-home-hero\\\">\\n  <div class=\\\"fisica-home-hero__inner\\\">\\n    <div class=\\\"fisica-home-hero__carousel fisica-home-carousel\\\" data-carousel>\\n      <div class=\\\"fisica-home-carousel__track\\\">\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/professora-instituto-fisica-uerj-participa-xxi-epef-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/09/WhatsApp-Image-2026-09-09-at-14.52.22.jpeg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Ensino de Física</span>\\n            <h3>Professora do Instituto de Física da UERJ participa da XXI EPEF, que celebrou 40 anos da pesquisa em Ensino de Física.</h3>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/projeto-rio-de-estrelas-inicia-jornada-divulgacao-cientifica-interior-estado/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/09/IMG_2806.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Extens&atilde;o</span>\\n            <h3>Projeto Rio de Estrelas inicia jornada de divulga&ccedil;&atilde;o cient&iacute;fica pelo interior do Estado</h3>\\n            <p>O GalileoMobile Rio de Estrelas leva a Astronomia e a divulga&ccedil;&atilde;o cient&iacute;fica a escolas p&uacute;blicas do interior do Estado do Rio de Janeiro.</p>\\n          </div>\\n        </a>\\n<a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/pesquisadores-instituto-fisica-uerj-ichep-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/08/20260805_082425.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Evento internacional</span>\\n            <h3>Pesquisadores do Instituto de F&iacute;sica da UERJ participam da ICHEP 2026, principal confer&ecirc;ncia mundial de F&iacute;sica de Altas Energias</h3>\\n            <p>Pesquisadores da UERJ que integram o grupo de F&iacute;sica de Altas Energias, juntamente com pesquisadores associados ao grupo da UFRGS, participaram da ICHEP 2026 (International Conference on High Energy Physics), realizada em Natal (RN).</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/professores-instituto-fisica-uerj-encontro-organizadores-olimpiadas-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/08/WhatsApp-Image-2026-08-19-at-16.45.45.jpeg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Extens&atilde;o</span>\\n            <h3>Professores do Instituto de F&iacute;sica da UERJ representam a Universidade no II Encontro Nacional de Organizadores de Olimp&iacute;adas e Competi&ccedil;&otilde;es de Conhecimento</h3>\\n            <p>No dia 13 de agosto de 2026, foi realizado o II Encontro Nacional com Organizadores de Olimp&iacute;adas, Torneios, Campeonatos, Feiras, Mostras, Pr&ecirc;mios e Concursos de Conhecimento, promovido pela SEEDUC-RJ, reunindo coordenadores e organizadores de importantes iniciativas voltadas &agrave; educa&ccedil;&atilde;o e &agrave; promo&ccedil;&atilde;o do conhecimento.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/visita-tecnica-inpe-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/03/PHOTO-2026-03-18-16-06-52-enhanced.png\');background-position:center 66%;\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Not&iacute;cia em destaque</span>\\n            <h3>Visita t&eacute;cnica ao Instituto Nacional de Pesquisas Espaciais</h3>\\n            <p>Com professores e estudantes do Instituto de F&iacute;sica da UERJ, a atividade refor&ccedil;ou a integra&ccedil;&atilde;o acad&ecirc;mica, a forma&ccedil;&atilde;o e a aproxima&ccedil;&atilde;o com centros de excel&ecirc;ncia.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/novos-equipamentos-laboratorios-mecanica-2026/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/03/PHOTO-2026-03-18-16-24-39.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Infraestrutura</span>\\n            <h3>Novos equipamentos para os laborat&oacute;rios de Mec&acirc;nica</h3>\\n            <p>Os investimentos ampliam as condi&ccedil;&otilde;es de ensino experimental e fortalecem a forma&ccedil;&atilde;o pr&aacute;tica nos cursos atendidos pelo Instituto.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/recepcao-dos-estudantes-2026-1/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/04/PHOTO-2026-03-18-16-03-28.jpg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Vida acad&ecirc;mica</span>\\n            <h3>Recep&ccedil;&atilde;o dos Estudantes 2026/1 integra calouros, veteranos e comunidade acad&ecirc;mica</h3>\\n            <p>Programa&ccedil;&atilde;o de acolhimento aproximou estudantes, egressos, laborat&oacute;rios e iniciativas de cuidado com a sa&uacute;de mental no in&iacute;cio do per&iacute;odo letivo.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/formatura-da-turma-de-2025-2/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/05/WhatsApp-Image-2026-05-05-at-15.51.44.jpeg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Vida acadêmica</span>\\n            <h3>Instituto de Física celebra formatura da turma de 2025/2</h3>\\n            <p>Depois de vários anos, o Instituto de Física da UERJ voltou a realizar uma festa de formatura de Licenciatura e Bacharelado, celebrando a conclusão de 20 estudantes da turma de 2025/2.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/instituto-de-fisica-recebe-novos-equipamentos-fisica-moderna/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/06/image0.jpeg\');\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Infraestrutura</span>\\n            <h3>Instituto de Física recebe novos equipamentos para Física Moderna</h3>\\n            <p>Aquisição fortalece o ensino experimental e amplia a formação científica dos estudantes de Física.</p>\\n          </div>\\n        </a>\\n        <a class=\\\"fisica-home-carousel__slide\\\" href=\\\"http://localhost/fisica/index.php/lancamento-livro-memorias-de-vida-professor-alberto-santoro/\\\" style=\\\"background-image:url(\'http://localhost/fisica/wp-content/uploads/2026/07/WhatsApp-Image-2026-07-24-at-12.59.29-1.jpeg\');background-position:center 25%;\\\">\\n          <div class=\\\"fisica-home-carousel__content\\\">\\n            <span class=\\\"fisica-home-carousel__label\\\">Memória institucional</span>\\n            <h3>Instituto de Física celebra lançamento do livro do Professor Alberto Santoro</h3>\\n            <p>O Instituto de Física da UERJ celebrou o lançamento de “Memórias de vida”, obra do Professor Alberto Santoro que reúne histórias profissionais, familiares e registros de uma trajetória fundamental para a Física na Universidade.</p>\\n          </div>\\n        </a>\\n                </div>\\n\\n      <div class=\\\"fisica-home-carousel__controls\\\">\\n        <button class=\\\"fisica-home-carousel__button\\\" type=\\\"button\\\" data-carousel-prev aria-label=\\\"Slide anterior\\\">&#10094;</button>\\n        <div class=\\\"fisica-home-carousel__dots\\\" data-carousel-dots></div>\\n        <button class=\\\"fisica-home-carousel__button\\\" type=\\\"button\\\" data-carousel-next aria-label=\\\"Pr&oacute;ximo slide\\\">&#10095;</button>\\n      </div>\\n    </div>\\n  </div>\\n</section>\\n\\n<script>\\n(() => {\\n  const root = document.querySelector(\'[data-carousel]\');\\n  if (!root || root.dataset.ready === \'true\') {\\n    return;\\n  }\\n  root.dataset.ready = \'true\';\\n\\n  const track = root.querySelector(\'.fisica-home-carousel__track\');\\n  const slides = Array.from(root.querySelectorAll(\'.fisica-home-carousel__slide\'));\\n  const next = root.querySelector(\'[data-carousel-next]\');\\n  const prev = root.querySelector(\'[data-carousel-prev]\');\\n  const dotsWrap = root.querySelector(\'[data-carousel-dots]\');\\n\\n  if (!track || !slides.length || !next || !prev || !dotsWrap) {\\n    return;\\n  }\\n\\n  let index = 0;\\n  let timer = null;\\n\\n  const dots = slides.map((_, i) => {\\n    const dot = document.createElement(\'button\');\\n    dot.type = \'button\';\\n    dot.className = \'fisica-home-carousel__dot\';\\n    dot.setAttribute(\'aria-label\', `Ir para slide ${i + 1}`);\\n    dot.addEventListener(\'click\', () => {\\n      goTo(i);\\n      restart();\\n    });\\n    dotsWrap.appendChild(dot);\\n    return dot;\\n  });\\n\\n  function render() {\\n    track.style.transform = `translateX(-${index * 100}%)`;\\n    dots.forEach((dot, dotIndex) => {\\n      dot.classList.toggle(\'is-active\', dotIndex === index);\\n    });\\n  }\\n\\n  function goTo(nextIndex) {\\n    index = (nextIndex + slides.length) % slides.length;\\n    render();\\n  }\\n\\n  function restart() {\\n    window.clearInterval(timer);\\n    timer = window.setInterval(() => goTo(index + 1), 5500);\\n  }\\n\\n  next.addEventListener(\'click\', () => {\\n    goTo(index + 1);\\n    restart();\\n  });\\n\\n  prev.addEventListener(\'click\', () => {\\n    goTo(index - 1);\\n    restart();\\n  });\\n\\n  render();\\n  restart();\\n})();\\n</script>\"},\"elements\":[],\"widgetType\":\"html\"}],\"isInner\":false},{\"id\":\"homeevents1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"eventhtml1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[fisica_eventos_destaques]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":false},{\"id\":\"labsanchor1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"labshtml1\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div id=\\\"laboratorios\\\"></div>\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"labsshort1\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[icones_servicos_uerj]\"},\"elements\"